_setFocusTrap() {
  const focusableSelector = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
  const focusableElements = this._element.querySelectorAll(focusableSelector)
  if (focusableElements.length === 0) return

  const firstElement = focusableElements[0]
  const lastElement = focusableElements[focusableElements.length - 1]

  this._focusTrapHandler = (event) => {
    if (event.key !== 'Tab') return

    const activeElement = document.activeElement
    if (!this._element.contains(activeElement) && activeElement !== this._element) return

    if (event.shiftKey) {
      if (activeElement === firstElement || activeElement === this._element) {
        event.preventDefault()
        lastElement.focus()
      }
    } else {
      if (activeElement === lastElement) {
        event.preventDefault()
        firstElement.focus()
      }
    }
  }

  this._element.addEventListener('keydown', this._focusTrapHandler)
}

